import { ITEMS_ENDPOINT } from '../config/api';

export interface Item {
  id: string;
  title: string;
}

export const PAGE_SIZE = 20;

export async function fetchItems(page: number): Promise<Item[]> {
  if (!Number.isInteger(page) || page < 1) throw new Error('Invalid page');
  const response = await fetch(`${ITEMS_ENDPOINT}?page=${page}&size=${PAGE_SIZE}`);
  if (!response.ok) throw new Error(`Request failed: ${response.status}`);
  const data: unknown = await response.json();
  if (!Array.isArray(data) || !data.every((item: unknown): item is Item =>
    typeof item === 'object' && item !== null &&
    'id' in item && typeof item.id === 'string' &&
    'title' in item && typeof item.title === 'string'
  )) throw new Error('Invalid items response');
  return data;
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { ActivityIndicator, FlatList, Pressable, SafeAreaView, StyleSheet, Text } from 'react-native';
import { fetchItems, PAGE_SIZE } from '../services/items';
import type { Item } from '../services/items';

export function ListScreen(): JSX.Element {
  const [items, setItems] = useState<Item[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const page = useRef(0);
  const hasMore = useRef(true);
  const busy = useRef(false);
  const active = useRef(false);
  const retryRefresh = useRef(false);

  const load = useCallback(async (replace: boolean): Promise<void> => {
    if (busy.current || (!replace && !hasMore.current)) return;
    busy.current = true;
    retryRefresh.current = replace;
    setLoading(true);
    setRefreshing(replace);
    setError(null);
    const nextPage = replace ? 1 : page.current + 1;
    try {
      const nextItems = await fetchItems(nextPage);
      if (!active.current) return;
      setItems(previous => replace ? nextItems :
        previous.concat(nextItems.filter(item => !previous.some(existing => existing.id === item.id))));
      page.current = nextPage;
      hasMore.current = nextItems.length === PAGE_SIZE;
    } catch (cause) {
      if (active.current) setError(cause instanceof Error ? cause.message : 'Failed to load items');
    } finally {
      busy.current = false;
      if (active.current) {
        setLoading(false);
        setRefreshing(false);
      }
    }
  }, []);

  useEffect(() => {
    active.current = true;
    void load(false);
    return () => { active.current = false; };
  }, [load]);

  return (
    <SafeAreaView style={styles.safe}>
      {loading && <ActivityIndicator accessibilityLabel="Loading items" />}
      {error !== null && <>
        <Text accessibilityRole="alert" accessibilityLiveRegion="polite">{error}</Text>
        <Pressable accessibilityRole="button" accessibilityLabel="Retry loading items"
          disabled={loading} accessibilityState={{ disabled: loading }}
          onPress={() => { void load(retryRefresh.current); }} style={styles.retry}>
          <Text>Retry</Text>
        </Pressable>
      </>}
      <FlatList data={items} keyExtractor={item => item.id}
        renderItem={({ item }) => <Text style={styles.row}>{item.title}</Text>}
        refreshing={refreshing} onRefresh={() => { void load(true); }}
        onEndReached={() => { if (error === null) void load(false); }}
        onEndReachedThreshold={0.5}
        ListEmptyComponent={!loading && error === null ? <Text>No items yet.</Text> : null} />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1 },
  row: { padding: 16, fontSize: 16 },
  retry: { padding: 16, minHeight: 48 },
});
